using System.Security.Claims;
using MaintenancePRO.Api.Contracts;
using MaintenancePRO.Api.Data;
using MaintenancePRO.Api.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/admin"),Authorize(Policy="AdminOnly")]
public sealed class AdminController(UserManager<ApplicationUser> users,AppDbContext db):ControllerBase {
 [HttpGet("users")] public async Task<IActionResult> UsersList([FromQuery]int page=1,[FromQuery]int pageSize=50){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=users.Users.AsNoTracking().OrderBy(x=>x.Email);var total=await q.CountAsync();var list=await q.Skip((page-1)*pageSize).Take(pageSize).ToListAsync();var result=new List<object>();foreach(var u in list)result.Add(new{id=u.Id,email=u.Email,displayName=u.DisplayName,status=u.Status,createdUtc=u.CreatedUtc,roles=await users.GetRolesAsync(u)});return Ok(new{page,pageSize,total,items=result});}
 [HttpPatch("users/{id}/status")] public async Task<IActionResult> SetStatus(string id,[FromBody]AccountStatus status){if(!Enum.IsDefined(status))return BadRequest(new{message="Statut invalide."});var u=await users.FindByIdAsync(id);if(u==null)return NotFound();if(u.Id==User.FindFirstValue(ClaimTypes.NameIdentifier))return BadRequest(new{message="Impossible de modifier son propre statut."});u.Status=status;var result=await users.UpdateAsync(u);if(!result.Succeeded)return BadRequest(new{errors=result.Errors.Select(e=>e.Code)});Audit("AccountStatusChanged","User",id);await db.SaveChangesAsync();return Ok(new{id=u.Id,email=u.Email,status=u.Status});}
 [HttpPut("users/{id}/role")] public async Task<IActionResult> SetRole(string id,[FromBody]SetRoleRequest r){var valid=new[]{AppRoles.Admin,AppRoles.Supervisor,AppRoles.Technician,AppRoles.User};if(!valid.Contains(r.Role))return BadRequest(new{message="Rôle invalide."});var u=await users.FindByIdAsync(id);if(u==null)return NotFound();if(u.Id==User.FindFirstValue(ClaimTypes.NameIdentifier))return BadRequest(new{message="Impossible de modifier son propre rôle."});var current=await users.GetRolesAsync(u);var remove=await users.RemoveFromRolesAsync(u,current);if(!remove.Succeeded)return BadRequest(new{errors=remove.Errors.Select(e=>e.Code)});var add=await users.AddToRoleAsync(u,r.Role);if(!add.Succeeded)return BadRequest(new{errors=add.Errors.Select(e=>e.Code)});Audit("UserRoleChanged","User",id);await db.SaveChangesAsync();return Ok(new{id=u.Id,role=r.Role});}
 [HttpGet("audit")] public async Task<IActionResult> AuditList([FromQuery]int take=100)=>Ok(await db.AuditEvents.AsNoTracking().OrderByDescending(x=>x.CreatedUtc).Take(Math.Clamp(take,1,500)).ToListAsync());
 [HttpGet("dashboard")] public async Task<IActionResult> Dashboard()=>Ok(new{equipmentCount=await db.Equipments.CountAsync(x=>x.Status!=EquipmentStatus.Retired),openBreakdowns=await db.Breakdowns.CountAsync(x=>x.Status!=BreakdownStatus.Resolved&&x.Status!=BreakdownStatus.Closed&&x.Status!=BreakdownStatus.Rejected),openInterventions=await db.Interventions.CountAsync(x=>x.Status!=InterventionStatus.Completed&&x.Status!=InterventionStatus.Cancelled&&x.Status!=InterventionStatus.Rejected),completedInterventions=await db.Interventions.CountAsync(x=>x.Status==InterventionStatus.Completed),pendingAccounts=await users.Users.CountAsync(x=>x.Status==AccountStatus.Pending)});
 private void Audit(string a,string type,string id)=>db.AuditEvents.Add(new AuditEvent{ActorUserId=User.FindFirstValue(ClaimTypes.NameIdentifier),Action=a,EntityType=type,EntityId=id,IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()});
}
